"""Independent native base-stat domains; generated bytes are not game saves."""
from functools import lru_cache
import os
from pathlib import Path
import struct
import tempfile
import tkinter as tk
import unittest
from unittest.mock import patch

from koei_editor.games.dw3.models import SaveError
from koei_editor.games.orochiz import orochiz_codec as codec
from koei_editor.games.orochiz import orochiz_parser as backend
from koei_editor.games.orochiz.orochiz_editor import Editor
from koei_editor.shared.experimental_limits import experimental_limits
from tests.test_orochiz_format import procedural_raw


@lru_cache(maxsize=1)
def normal_stats_raw():
    raw = bytearray(procedural_raw())
    for officer in range(96):
        start = 0xC + officer * 0xDC
        for relative, minima in ((4, backend.BASE_LIFE_MINIMUMS),
                                 (6, backend.BASE_MUSOU_MINIMUMS),
                                 (10, backend.BASE_DEFENSE_MINIMUMS),
                                 (12, backend.BASE_SPEED_MINIMUMS)):
            struct.pack_into('<H', raw, start + relative, minima[officer])
    return codec.encode(raw)


class OrochiZBaseStatsTests(unittest.TestCase):
    def test_every_officer_stat_has_independent_surgical_bounds_and_no_progression_write(self):
        document = backend.decode(normal_stats_raw())
        fields = [field for field in backend.fields_for(document) if field.group == 'Officer base stats']
        self.assertEqual(len(fields), 384)
        self.assertEqual(backend.serialize(document, {}), document.raw)
        for field in fields:
            for value in {field.minimum, field.maximum}:
                with self.subTest(field=field.id, value=value):
                    pending = backend.stage(document, {}, field.id, value)
                    raw = backend.serialize(document, pending)
                    expected = bytearray(document.raw)
                    struct.pack_into('<H', expected, field.offset, value)
                    self.assertEqual(raw, codec.encode(expected))
                    self.assertEqual(field.value(backend.decode(raw).payload), value)
                    self.assertEqual(backend.stage(document, pending, field.id,
                                                  field.value(document.payload)), {})
            for value in (field.minimum - 1, field.maximum + 1, True, 1.0, '200'):
                with self.subTest(field=field.id, rejected=value), self.assertRaises(SaveError):
                    backend.serialize(document, {field.id: value})
        self.assertEqual(document.raw[-16:], backend.serialize(document, backend.maximums(document, {}))[-16:])

    def test_new_stats_are_opaque_for_unusual_originals_even_in_experimental_mode(self):
        for key, relative in (('life', 4), ('musou', 6), ('defense', 10), ('speed', 12)):
            for unusual in (0, 65535):
                raw = bytearray(normal_stats_raw())
                struct.pack_into('<H', raw, 0xC + relative, unusual)
                document = backend.decode(codec.encode(raw))
                field_id = f'officer_0_base_{key}'
                for enabled in (False, True):
                    with experimental_limits(enabled):
                        self.assertNotIn(field_id, backend.field_map(document))
                        with self.assertRaises(SaveError):
                            backend.stage(document, {}, field_id, 200)
                        saved = backend.serialize(document, backend.maximums(document, {}, 'Officer base stats'))
                        self.assertEqual(saved[0xC + relative:0xC + relative + 2],
                                         unusual.to_bytes(2, 'little'))
                        self.assertIn(f'officer_1_base_{key}', backend.field_map(document))

    def test_experimental_width_does_not_expand_minimum_and_higher_reopen_stays_opaque(self):
        document = backend.decode(normal_stats_raw())
        field = backend.field_map(document)['officer_0_base_life']
        with experimental_limits():
            pending = backend.stage(document, {}, field.id, 65535)
            raw = backend.serialize(document, pending)
            self.assertEqual(raw[field.offset:field.offset + 2], b'\xff\xff')
            for value in (65536, -1, field.minimum - 1, True):
                with self.subTest(value=value), self.assertRaises(SaveError):
                    backend.stage(document, {}, field.id, value)
            reopened = backend.decode(raw)
            self.assertNotIn(field.id, backend.field_map(reopened))
            self.assertEqual(backend.serialize(reopened, {}), raw)

    def test_combined_base_stat_copy_retains_review_backup_and_restore(self):
        with tempfile.TemporaryDirectory() as folder:
            source = Path(folder) / 'copy.dat'
            source.write_bytes(normal_stats_raw())
            document = backend.read_save(source)
            fields = [field for field in backend.fields_for(document)
                      if field.group == 'Officer base stats' and field.slot in (1, 96)]
            pending = {field.id: field.maximum for field in fields
                       if field.value(document.payload) != field.maximum}
            frozen = dict(pending)
            self.assertEqual(len(backend.review(document, pending)), len(pending))
            destination = Path(folder) / 'edited.dat'
            reopened = backend.save_as(document, pending, destination)
            self.assertEqual(pending, frozen)
            self.assertEqual(reopened.raw, destination.read_bytes())
            for field in fields:
                self.assertEqual(field.value(reopened.payload), pending.get(field.id, field.value(document.payload)))
            self.assertEqual(source.read_bytes(), document.raw)
            snapshots = list((source.parent / 'UniversalEditorBackups').glob('*.dat'))
            self.assertEqual(len(snapshots), 1)
            restored = backend.restore(snapshots[0], Path(folder) / 'restored.dat')
            self.assertEqual(restored.read_bytes(), source.read_bytes())
            with self.assertRaises(FileExistsError):
                backend.save_as(document, pending, destination)

    def test_gui_base_stats_selection_review_undo_and_new_copy(self):
        try:
            root = tk.Tk()
        except tk.TclError as error:
            self.skipTest(f'Tk display unavailable: {error}')
        self.addCleanup(root.destroy)
        root.withdraw()
        with tempfile.TemporaryDirectory() as folder:
            source = Path(folder) / 'copy.dat'
            source.write_bytes(normal_stats_raw())
            editor = Editor(root)
            with patch('koei_editor.shared.verified_gui.messagebox.showerror') as errors:
                with patch('koei_editor.shared.verified_gui.filedialog.askopenfilename', return_value=str(source)):
                    editor.open()
                key = 'officer_0_base_defense'
                editor.group.set('Officer base stats')
                editor.search.set(key)
                editor.refresh()
                editor.fields.selection_set(key)
                editor.selected()
                editor.value.set('200')
                editor.apply_selected()
                self.assertEqual(editor.changes, {key: 200})
                editor.review()
                editor.undo()
                self.assertEqual(editor.changes, {})
                editor.stage_values({key: 200})
                destination = Path(folder) / 'gui-edited.dat'
                editor.save_to(destination)
                self.assertEqual(backend.field_map(backend.read_save(destination))[key].value(destination.read_bytes()), 200)
                self.assertEqual(source.read_bytes(), normal_stats_raw())
                errors.assert_not_called()

    @unittest.skipUnless(os.environ.get('OROCHIZ_NATIVE_SAVE'), 'Private native Z copy unavailable')
    def test_genuine_source_new_stats_are_surgical_and_original_unchanged(self):
        source = Path(os.environ['OROCHIZ_NATIVE_SAVE'])
        original = source.read_bytes()
        document = backend.decode(original)
        fields = [field for field in backend.fields_for(document) if field.group == 'Officer base stats']
        self.assertGreater(len(fields), 300)
        for field in fields:
            value = field.minimum if field.value(original) != field.minimum else field.maximum
            expected = bytearray(original)
            struct.pack_into('<H', expected, field.offset, value)
            self.assertEqual(backend.serialize(document, {field.id: value}), codec.encode(expected))
        self.assertEqual(source.read_bytes(), original)
